# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANIN İFADESİ VE DERECELERİ: İCMALÎ-TAFSİLÎ, TAKLİDÎ-TAHKİKÎ (TDB.9.2.1)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">KELİMEİTEVHİT, KELİMEİŞEHADET VE KAPSAM</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Kelimeitevhit (Tevhid İlkesi):</text>\n  <text x="50" y="110" font-size="10.5" fill="#1e40af">"Lâ ilâhe illallah Muhammedün Resûlullah"</text>\n  <text x="42" y="132" font-size="11" font-weight="bold" fill="#1e3a8a">• Kelimeişehadet (Şahitlik ve İkrar):</text>\n  <text x="50" y="148" font-size="10.5" fill="#1e40af">"Eşhedü en lâ ilâhe illallah ve eşhedü enne..."</text>\n  <text x="42" y="172" font-size="11" font-weight="bold" fill="#1e3a8a">• İcmalî İman (Özlü/Toplu İman):</text>\n  <text x="50" y="188" font-size="10.5" fill="#1e40af">İnanç esaslarına ayrıntıya girmeden toptan inanmak.</text>\n  <text x="42" y="210" font-size="11" font-weight="bold" fill="#1e3a8a">• Tafsilî İman (Ayrıntılı İman):</text>\n  <text x="50" y="226" font-size="10.5" fill="#1e40af">Altı iman esasının her birine ayrı ayrı inanmak.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TAKLİDÎ İMANDAN TAHKİKÎ İMANA GEÇİŞ</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#14532d">• Taklidî İman:</text>\n  <text x="385" y="112" font-size="10.5" fill="#166534">Delillere dayanmadan, aile ve sosyal çevreden</text>\n  <text x="385" y="127" font-size="10.5" fill="#166534">görüldüğü şekliyle benimsenen imandır; şüpheler</text>\n  <text x="385" y="142" font-size="10.5" fill="#166534">karşısında sarsılma riski taşır.</text>\n  <text x="377" y="168" font-size="11" font-weight="bold" fill="#14532d">• Tahkikî İman:</text>\n  <text x="385" y="184" font-size="10.5" fill="#166534">Akıl, tefekkür, ilim, Kur\'an ve sünnet delilleriyle</text>\n  <text x="385" y="199" font-size="10.5" fill="#166534">araştırılarak içselleştirilen bilinçli imandır;</text>\n  <text x="385" y="214" font-size="10.5" fill="#166534">ihlas, takva ve salih amelle kemâle erer.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANIN GEÇERLİLİK ŞARTLARI VE İNANÇ BAKIMINDAN İNSANLAR</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">İMANIN GEÇERLİ OLMASININ ŞARTLARI</text>\n  <text x="42" y="96" font-size="10.5" fill="#713f12">1. Dinin kesin hükümlerini (farz/haram) inkâr etmemek</text>\n  <text x="42" y="120" font-size="10.5" fill="#713f12">2. Kur\'an-ı Kerim ayetlerinin tamamına bütünüyle inanmak</text>\n  <text x="42" y="144" font-size="10.5" fill="#713f12">3. Korku (havf) ile ümit (recâ) dengesinde bulunmak</text>\n  <text x="42" y="168" font-size="10.5" fill="#713f12">4. İmanı ölüm anına (ye\'s hâline) ertelememek</text>\n  <text x="42" y="192" font-size="10.5" fill="#713f12">5. Baskı ve zorlama olmadan hür iradeyle tasdik etmek</text>\n  <text x="42" y="216" font-size="10.5" font-weight="bold" fill="#854d0e">• Teklif ve Mükellef: Akıl ve ergenlik (büluğ) şartı</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">İNANÇ BAKIMINDAN İNSANLAR</text>\n  <text x="377" y="96" font-size="10.5" fill="#581c87">• Mümin: Kalbiyle tasdik edip diliyle ikrar eden kişi</text>\n  <text x="377" y="120" font-size="10.5" fill="#581c87">• Münafık: Kalben inanmadığı hâlde inanmış görünen</text>\n  <text x="377" y="144" font-size="10.5" fill="#581c87">• Kâfir: İman esaslarını bütünüyle veya kısmen reddeden</text>\n  <text x="377" y="168" font-size="10.5" fill="#581c87">• Müşrik: Allah\'ın zat, sıfat ve fiillerine ortak koşan</text>\n  <text x="377" y="192" font-size="10.5" fill="#581c87">• Fasık: İlahi emirlere itaatten ayrılıp günaha dalan</text>\n  <text x="377" y="216" font-size="10.5" font-weight="bold" fill="#6b21a8">• İhlas ve Takva: Riya ve gösterişten arınmış kulluk</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AMENTÜ DUASI VE İSLAM İNANÇ ESASLARI (USÛL-İ SİTTE — TDB.9.2.2)</text>\n  <rect x="20" y="45" width="210" height="90" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. ALLAH\'A (CC) İMAN</text>\n  <text x="32" y="86" font-size="10" fill="#1e3a8a">Tevhid, İhlas suresi, yaratıcı,</text>\n  <text x="32" y="102" font-size="10" fill="#1e3a8a">esmayıhüsna, zatî-subûtî sıfatlar.</text>\n  <rect x="245" y="45" width="210" height="90" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. MELEKLERE İMAN</text>\n  <text x="257" y="86" font-size="10" fill="#14532d">Nurdan yaratılan, günahsız varlıklar:</text>\n  <text x="257" y="102" font-size="10" fill="#14532d">Cebrail, Mikail, İsrafil, Azrail, Kiramen.</text>\n  <rect x="470" y="45" width="210" height="90" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="1.8"/>\n  <text x="575" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">3. KİTAPLARA İMAN</text>\n  <text x="482" y="86" font-size="10" fill="#713f12">Suhuf ve dört ilahi vahiy: Tevrat,</text>\n  <text x="482" y="102" font-size="10" fill="#713f12">Zebur, İncil ve korunan Kur\'an-ı Kerim.</text>\n  <rect x="20" y="150" width="210" height="90" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="125" y="171" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. PEYGAMBERLERE İMAN</text>\n  <text x="32" y="191" font-size="10" fill="#581c87">Hz. Âdem\'den son elçi (Hâtemü\'l-Enbiyâ)</text>\n  <text x="32" y="207" font-size="10" fill="#581c87">Hz. Muhammed\'e (sav) resul ve nebiler.</text>\n  <rect x="245" y="150" width="210" height="90" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="350" y="171" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">5. AHİRETE İMAN</text>\n  <text x="257" y="191" font-size="10" fill="#7c2d12">Kıyamet, ba\'s (yeniden diriliş), haşir,</text>\n  <text x="257" y="207" font-size="10" fill="#7c2d12">hesap, mizan, cennet ve cehennem.</text>\n  <rect x="470" y="150" width="210" height="90" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="575" y="171" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">6. KADER VE KAZAYA İMAN</text>\n  <text x="482" y="191" font-size="10" fill="#7f1d1d">İlahi ölçü/plan (kader), gerçekleşme</text>\n  <text x="482" y="207" font-size="10" fill="#7f1d1d">(kaza), küllî-cüz\'î irade ve tevekkül.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
